import { Decimal, ZERO } from '../../common/decimal';
import type { ItemResult, Recommendation, Summary } from './types';

const PRICE_STEP = new Decimal('0.50');
const COST_REDUCTION = new Decimal('0.10');
const HIGH_FOOD_COST_PERCENT = new Decimal(35);
const LOW_COVERAGE_PERCENT = new Decimal(80);
const MAX_RECOMMENDATIONS = 6;

const money = (value: Decimal) => value.toDecimalPlaces(2, Decimal.ROUND_HALF_UP).toFixed(2);

/**
 * Rule-based recommendations. Every impact figure is computed here at constant sales volume;
 * nothing is generated by a language model. Ordered by impact, data-quality items last.
 */
export function buildRecommendations(items: ItemResult[], summary: Summary, currency: string): Recommendation[] {
  const recommendations: Recommendation[] = [
    ...priceIncreases(items, currency),
    ...costReductions(items, currency),
    ...promotions(items),
    ...reviews(items),
  ].sort((a, b) => (b.impactGp ?? ZERO).comparedTo(a.impactGp ?? ZERO));

  const coverage = coverageRecommendation(items, summary);
  return [...recommendations.slice(0, MAX_RECOMMENDATIONS - (coverage ? 1 : 0)), ...(coverage ? [coverage] : [])].map(
    (recommendation, index) => ({ ...recommendation, priority: index + 1 }),
  );
}

/** Popular items with below-average GP: a small price rise is the cheapest lever. */
function priceIncreases(items: ItemResult[], currency: string): Recommendation[] {
  return items
    .filter((item) => item.matrixClass === 'PLOWHORSE')
    .sort((a, b) => b.unitsSold.comparedTo(a.unitsSold))
    .slice(0, 2)
    .map((item) => {
      const netIncrease = PRICE_STEP.dividedBy((item.vatRate ?? ZERO).plus(1));
      const impact = netIncrease.times(item.unitsSold);
      return {
        kind: 'PRICE' as const,
        priority: 0,
        title: `Raise the price of ${item.name} by ${currency} ${money(PRICE_STEP)}`,
        body: `${item.name} sells well (${item.unitsSold.toFixed(0)} units) but earns below the category's average gross profit per portion. At the same sales volume, +${currency} ${money(PRICE_STEP)} adds about ${currency} ${money(impact)} gross profit over the analysed period.`,
        menuItemId: item.menuItemId,
        impactGp: impact,
      };
    });
}

/** Items whose ingredient cost is a large share of the net price. */
function costReductions(items: ItemResult[], currency: string): Recommendation[] {
  return items
    .filter((item) => item.foodCostPercent.value?.gt(HIGH_FOOD_COST_PERCENT) && item.unitsSold.gt(0))
    .sort((a, b) => (b.costPerPortion.value as Decimal).times(b.unitsSold).comparedTo((a.costPerPortion.value as Decimal).times(a.unitsSold)))
    .slice(0, 2)
    .map((item) => {
      const impact = (item.costPerPortion.value as Decimal).times(COST_REDUCTION).times(item.unitsSold);
      return {
        kind: 'COST' as const,
        priority: 0,
        title: `Review the recipe or portion of ${item.name}`,
        body: `Ingredients cost ${money(item.foodCostPercent.value as Decimal)}% of the net price. Reducing the cost per portion by 10% (portion size, supplier or ingredient swap) adds about ${currency} ${money(impact)} gross profit over the analysed period.`,
        menuItemId: item.menuItemId,
        impactGp: impact,
      };
    });
}

function promotions(items: ItemResult[]): Recommendation[] {
  return items
    .filter((item) => item.matrixClass === 'PUZZLE')
    .sort((a, b) => (b.gpPerPortion.value as Decimal).comparedTo(a.gpPerPortion.value as Decimal))
    .slice(0, 2)
    .map((item) => ({
      kind: 'MENU_MIX' as const,
      priority: 0,
      title: `Promote ${item.name}`,
      body: `${item.name} is highly profitable per portion but sells less than its category average. Better menu placement, staff recommendation or a description update could lift its sales.`,
      menuItemId: item.menuItemId,
      impactGp: null,
    }));
}

function reviews(items: ItemResult[]): Recommendation[] {
  return items
    .filter((item) => item.matrixClass === 'DOG')
    .sort((a, b) => (a.theoreticalGp.value ?? ZERO).comparedTo(b.theoreticalGp.value ?? ZERO))
    .slice(0, 2)
    .map((item) => ({
      kind: 'MENU_MIX' as const,
      priority: 0,
      title: `Rework or remove ${item.name}`,
      body: `${item.name} is below average in both popularity and gross profit per portion within its category. Consider re-pricing, reworking the recipe, or replacing it.`,
      menuItemId: item.menuItemId,
      impactGp: null,
    }));
}

function coverageRecommendation(items: ItemResult[], summary: Summary): Recommendation | null {
  if (summary.revenueCoveredPercent && summary.revenueCoveredPercent.gte(LOW_COVERAGE_PERCENT)) return null;
  const missing = items
    .filter((item) => !item.costPerPortion.value && item.unitsSold.gt(0))
    .sort((a, b) => b.unitsSold.comparedTo(a.unitsSold))
    .slice(0, 5)
    .map((item) => item.name);
  if (!missing.length) return null;
  return {
    kind: 'DATA_QUALITY',
    priority: 0,
    title: 'Add recipes for your best sellers',
    body: `Gross profit can't be calculated yet for: ${missing.join(', ')}. Tell the assistant what goes into each dish (ingredients and quantities) to complete the analysis.`,
    menuItemId: null,
    impactGp: null,
  };
}
